WITH filtered AS (SELECT id, product_name, category, brand, cost, stock_qty, launch_date, tags, supplier_id, ADD_MONTHS(launch_date, 12) AS launch_date_plus_months FROM products WHERE price BETWEEN 400 AND 1010 AND brand IS NOT NULL) SELECT s.country, a.brand, COUNT(*) AS rows_total, MAX(a.cost) AS max_cost, MIN(a.stock_qty) AS min_stock_qty FROM filtered a LEFT JOIN suppliers s ON a.supplier_id = s.id GROUP BY s.country, a.brand;
